import openpyxl

wb = openpyxl.load_workbook('sales_data.xlsx')
print("Sheets:", wb.sheetnames)
for name in wb.sheetnames:
    ws = wb[name]
    print(f"\n=== Sheet: {name} (dims: {ws.dimensions}, max_row={ws.max_row}, max_col={ws.max_column}) ===")
    for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row, 12)):
        vals = [(c.coordinate, c.value) for c in row if c.value is not None]
        if vals:
            print(vals)

import zipfile, re

z = zipfile.ZipFile('sales_data.xlsx')
for n in z.namelist():
    print(n, z.getinfo(n).file_size)

for n in ['xl/workbook.xml', 'xl/sharedStrings.xml', 'xl/worksheets/sheet1.xml']:
    try:
        data = z.read(n).decode('utf-8')
    except KeyError:
        print(f"\n--- {n}: MISSING ---")
        continue
    print(f"\n--- {n} ---")
    print(data[:6000])

